ALTER TABLE "payment_operation_roster_snapshots" ADD CONSTRAINT "payment_operation_roster_snapshots_amount_check" CHECK ("payment_operation_roster_snapshots"."amount_minor" > 0 AND "payment_operation_roster_snapshots"."currency" = 'USD' AND "payment_operation_roster_snapshots"."snapshot_version" IN (2, 3) AND "payment_operation_roster_snapshots"."snapshot_kind" IN ('interactive', 'standing_autopay') AND (("payment_operation_roster_snapshots"."snapshot_kind" = 'interactive' AND "payment_operation_roster_snapshots"."collection_mode" IS NULL AND "payment_operation_roster_snapshots"."cutoff_at" IS NULL AND "payment_operation_roster_snapshots"."request_kind" IN ('direct', 'order') AND "payment_operation_roster_snapshots"."encrypted_source_id" IS NOT NULL AND "payment_operation_roster_snapshots"."payer_bowler_id" IS NOT NULL AND "payment_operation_roster_snapshots"."source_kind" IN ('new_card', 'saved_card', 'wallet') AND "payment_operation_roster_snapshots"."quote_fingerprint" IS NOT NULL AND (("payment_operation_roster_snapshots"."snapshot_version" = 2 AND "payment_operation_roster_snapshots"."partner_evidence" IS NULL) OR ("payment_operation_roster_snapshots"."snapshot_version" = 3 AND "payment_operation_roster_snapshots"."partner_evidence" IS NOT NULL AND jsonb_typeof("payment_operation_roster_snapshots"."partner_evidence") = 'array' AND jsonb_array_length("payment_operation_roster_snapshots"."partner_evidence") > 0))) OR ("payment_operation_roster_snapshots"."snapshot_kind" = 'standing_autopay' AND "payment_operation_roster_snapshots"."snapshot_version" = 2 AND "payment_operation_roster_snapshots"."collection_mode" IN ('weekly', 'double_pay') AND "payment_operation_roster_snapshots"."cutoff_at" IS NOT NULL AND "payment_operation_roster_snapshots"."request_kind" IS NULL AND "payment_operation_roster_snapshots"."encrypted_source_id" IS NULL AND "payment_operation_roster_snapshots"."payer_bowler_id" IS NULL AND "payment_operation_roster_snapshots"."source_kind" IS NULL AND "payment_operation_roster_snapshots"."quote_fingerprint" IS NULL AND "payment_operation_roster_snapshots"."partner_evidence" IS NULL)));--> statement-breakpoint
ALTER TABLE "payment_operation_roster_snapshots" ADD CONSTRAINT "payment_operation_roster_snapshots_fingerprint_check" CHECK (("payment_operation_roster_snapshots"."snapshot_version" = 2 AND "payment_operation_roster_snapshots"."snapshot_fingerprint" ~ '^lv(rosterexec|standingcutoff):v1:[0-9a-f]{64}$') OR ("payment_operation_roster_snapshots"."snapshot_version" = 3 AND "payment_operation_roster_snapshots"."snapshot_fingerprint" ~ '^lvpartnerexec:v3:[0-9a-f]{64}$'));--> statement-breakpoint
ALTER TABLE "payment_operation_roster_snapshots" ADD CONSTRAINT "payment_operation_roster_snapshots_quote_fingerprint_check" CHECK (("payment_operation_roster_snapshots"."quote_fingerprint" IS NULL AND "payment_operation_roster_snapshots"."snapshot_kind" = 'standing_autopay') OR ("payment_operation_roster_snapshots"."quote_fingerprint" ~ '^lvrosterquote:v1:[0-9a-f]{64}$' AND "payment_operation_roster_snapshots"."snapshot_version" = 2 AND "payment_operation_roster_snapshots"."snapshot_kind" = 'interactive') OR ("payment_operation_roster_snapshots"."quote_fingerprint" ~ '^lvpartnerquote:v3:[0-9a-f]{64}$' AND "payment_operation_roster_snapshots"."snapshot_version" = 3 AND "payment_operation_roster_snapshots"."snapshot_kind" = 'interactive'));